        "description"
      ],
      "title": "_Risk",
      "type": "object"
    }
  },
  "properties": {
    "risks": {
      "default": [],
      "items": {
        "$ref": "#/$defs/_Risk"
      },
      "title": "Risks",
      "type": "array"
    }
  },
  "title": "RiskList",
  "type": "object"
}

Example instance (the shape your response must take, with placeholder values — replace them with real values):
