        "text": {
          "title": "Text",
          "type": "string"
        }
      },
      "required": [
        "text",
        "confidence"
      ],
      "title": "ResearcherClaim",
      "type": "object"
    }
  },
  "properties": {
    "claims": {
      "items": {
