          "type": "string"
        },
        "related_claim_texts": {
          "default": [],
          "items": {
            "type": "string"
          },
          "title": "Related Claim Texts",
          "type": "array"
        },
        "severity": {
          "default": "medium",
          "pattern": "^(low|medium|high)$",
          "title": "Severity",
          "type": "string"
        },
        "title": {
          "title": "Title",
          "type": "string"
        }
      },
      "required": [
        "title",
        "description"
      ],
      "title": "_Risk",
      "type": "object"
    }
  },
  "properties": {
    "risks": {
      "default": [],
      "items": {
        "$ref": "#/$defs/_Risk"
      },
      "title": "Risks",
      "type": "array"
    }
  },
  "title": "RiskList",
  "type": "object"
}

Example instance (the shape your response must take, with placeholder values — replace them with real values):
